	/* @Test */
	public void testCompileSleighProgram()
    {
		using (ToyDBTraceBuilder b = new ToyDBTraceBuilder("test", TOY_BE_64_HARVARD))
{
			PcodeProgram sp = SleighProgramCompiler.compileProgram((SleighLanguage) b.language,
				"test", """
						if (r0) goto <else>;
						    r1 = 6;
						    goto <done>;
						<else>
						    r1 = 7;
						<done>
						""", PcodeUseropLibrary.NIL);
			TraceThread thread;
			try (Transaction tx = b.startTransaction()) {
				b.createRootObject(buildContext(), "Target");
				thread = b.getOrAddThread("Threads[1]", 0);
				b.createObjectsFramesAndRegs(thread, Lifespan.nowOn(0), b.host, 1);
				PcodeExecutor<byte[]> executor =
					TraceSleighUtils.buildByteExecutor(b.host, 0, thread, 0);
				sp.execute(executor, PcodeUseropLibrary.nil());
			}

			Register r1 = b.language.getRegister("r1");
			assertEquals(BigInteger.valueOf(6),
				b.trace.getMemoryManager()
						.getMemoryRegisterSpace(thread, false)
						.getValue(0, r1)
						.getUnsignedValue());
		}
	}
